import 'package:cerne/features/capture/presentation/widgets/capture_tab_bar.dart';
import 'package:cerne/features/capture/presentation/widgets/foto_tab_view.dart';
import 'package:cerne/features/capture/presentation/widgets/texto_tab_view.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// Shown via `showModalBottomSheet` as an overlay above Home/Chat (with a
/// darkened scrim) without discarding or navigating away from Home/Chat's
/// state underneath (FR-001) — `showModalBottomSheet` gives the scrim and
/// overlay semantics for free. An exhaustive `BlocBuilder` switch over
/// [InsertionModalState] drives the three tab bodies, plus a listener on
/// the bloc's one-shot [InsertionModalBloc.closeRequests] that pops the
/// sheet on a successful save (FR-011).
class InsertionModalPage extends StatefulWidget {
  const InsertionModalPage({super.key});

  @override
  State<InsertionModalPage> createState() => _InsertionModalPageState();
}

class _InsertionModalPageState extends State<InsertionModalPage> {
  late final StreamSubscription<void> _closeSubscription;

  @override
  void initState() {
    super.initState();
    _closeSubscription = context.read<InsertionModalBloc>().closeRequests.listen(
      (_) {
        if (mounted && Navigator.of(context).canPop()) {
          Navigator.of(context).pop();
        }
      },
    );
  }

  @override
  void dispose() {
    _closeSubscription.cancel();
    super.dispose();
  }

  CaptureTab _tabOf(InsertionModalState state) => switch (state) {
    InsertionModalTexto() ||
    InsertionModalTextoSaving() ||
    InsertionModalTextoFailure() => CaptureTab.texto,
    InsertionModalAudioPermissionDenied() ||
    InsertionModalAudioRecording() ||
    InsertionModalAudioSaving() ||
    InsertionModalAudioFailure() => CaptureTab.audio,
    InsertionModalFotoCaptura() ||
    InsertionModalFotoPermissionDenied() ||
    InsertionModalFotoSaving() ||
    InsertionModalFotoFailure() => CaptureTab.foto,
  };

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.all(DesignTokens.spacingMd),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Expanded(
                  child: Text('Nova entrada', style: DesignTokens.textTitleLg),
                ),
                IconButton(
                  onPressed: () {
                    context.read<InsertionModalBloc>().add(const ModalClosed());
                    Navigator.of(context).pop();
                  },
                  icon: const Icon(Icons.close),
                ),
              ],
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            BlocBuilder<InsertionModalBloc, InsertionModalState>(
              builder: (context, state) {
                return Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    CaptureTabBar(
                      activeTab: _tabOf(state),
                      onTabSelected: (tab) =>
                          context.read<InsertionModalBloc>().add(TabSelected(tab)),
                    ),
                    const SizedBox(height: DesignTokens.spacingMd),
                    switch (state) {
                      InsertionModalTexto() ||
                      InsertionModalTextoSaving() ||
                      InsertionModalTextoFailure() => TextoTabView(state: state),
                      InsertionModalAudioPermissionDenied() ||
                      InsertionModalAudioRecording() ||
                      InsertionModalAudioSaving() ||
                      InsertionModalAudioFailure() => AudioTabView(state: state),
                      InsertionModalFotoCaptura() ||
                      InsertionModalFotoPermissionDenied() ||
                      InsertionModalFotoSaving() ||
                      InsertionModalFotoFailure() => FotoTabView(state: state),
                    },
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/di/service_locator.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/pages/insertion_modal_page.dart';
import 'package:cerne/features/home/presentation/widgets/app_drawer.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// Fixed dark-green header (☰ + "Cerne" wordmark) and an empty conversation
/// area, plus a composer bar that is rendered but fully disabled — no fake
/// messages, no RF04 wiring (FR-016; research.md R10). Scaffold's `drawer`
/// gives the ☰ icon its tap target for free (User Story 4).
class HomeChatShellPage extends StatelessWidget {
  const HomeChatShellPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      drawer: const AppDrawer(),
      appBar: AppBar(
        backgroundColor: DesignTokens.colorPrimary,
        foregroundColor: DesignTokens.colorOnPrimary,
        title: Text(
          'Cerne',
          style: DesignTokens.textTitleLg.copyWith(
            color: DesignTokens.colorOnPrimary,
          ),
        ),
      ),
      body: Column(
        children: [
          const Expanded(child: SizedBox.expand()),
          _ComposerBar(),
        ],
      ),
    );
  }
}

void _openInsertionModal(BuildContext context) {
  showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    builder: (_) => BlocProvider(
      create: (_) => getIt<InsertionModalBloc>(),
      child: const InsertionModalPage(),
    ),
  );
}

class _ComposerBar extends StatelessWidget {
  const _ComposerBar();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        border: Border(top: BorderSide(color: DesignTokens.colorBorder)),
      ),
      child: Row(
        children: [
          IconButton(
            onPressed: () => _openInsertionModal(context),
            icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
          ),
          Expanded(
            child: TextField(
              enabled: false,
              decoration: const InputDecoration(
                hintText: 'Escreva uma mensagem...',
              ),
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          IconButton(
            onPressed: null,
            icon: const Icon(Icons.send, color: DesignTokens.colorTextSecondary),
          ),
        ],
      ),
    );
  }
}

