import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// The plain generic loading indicator every Save/recognition call in this
/// unit shows — no dedicated multi-state recognition screen (FR-007).
class CaptureLoadingIndicator extends StatelessWidget {
  const CaptureLoadingIndicator({super.key});

  @override
  Widget build(BuildContext context) {
    return const Center(
      child: SizedBox(
        width: DesignTokens.sizeLoadingIndicator,
        height: DesignTokens.sizeLoadingIndicator,
        child: CircularProgressIndicator(
          strokeWidth: DesignTokens.strokeWidthLoadingIndicator,
        ),
      ),
    );
  }
}

/// A plain message plus one generic retry action — deliberately not the
/// prototype's named "Erro" states (research.md R11, FR-009).
class CaptureFailureBand extends StatelessWidget {
  const CaptureFailureBand({
    required this.message,
    required this.onRetry,
    super.key,
  });

  final String message;
  final VoidCallback onRetry;

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(
          message,
          textAlign: TextAlign.center,
          style: DesignTokens.textBodyMd.copyWith(color: DesignTokens.colorError),
        ),
        const SizedBox(height: DesignTokens.spacingMd),
        OutlinedButton(onPressed: onRetry, child: const Text('Tentar de novo')),
      ],
    );
  }
}

/// Shown in place of the recording/capture controls (Edge Cases).
class CapturePermissionDeniedMessage extends StatelessWidget {
  const CapturePermissionDeniedMessage({required this.message, super.key});

  final String message;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Text(
        message,
        textAlign: TextAlign.center,
        style: DesignTokens.textBodyMd.copyWith(
          color: DesignTokens.colorTextSecondary,
        ),
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
import 'package:flutter/material.dart';

/// Exactly three capture modes as tabs, with the active tab visually
/// distinguished (FR-002).
class CaptureTabBar extends StatelessWidget {
  const CaptureTabBar({
    required this.activeTab,
    required this.onTabSelected,
    super.key,
  });

  final CaptureTab activeTab;
  final ValueChanged<CaptureTab> onTabSelected;

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Expanded(
          child: _TabButton(
            label: 'Texto',
            tab: CaptureTab.texto,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
        const SizedBox(width: DesignTokens.spacingSm),
        Expanded(
          child: _TabButton(
            label: 'Áudio',
            tab: CaptureTab.audio,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
        const SizedBox(width: DesignTokens.spacingSm),
        Expanded(
          child: _TabButton(
            label: 'Foto',
            tab: CaptureTab.foto,
            activeTab: activeTab,
            onTabSelected: onTabSelected,
          ),
        ),
      ],
    );
  }
}

class _TabButton extends StatelessWidget {
  const _TabButton({
    required this.label,
    required this.tab,
    required this.activeTab,
    required this.onTabSelected,
  });

  final String label;
  final CaptureTab tab;
  final CaptureTab activeTab;
  final ValueChanged<CaptureTab> onTabSelected;

  @override
  Widget build(BuildContext context) {
    final isActive = tab == activeTab;
    return GestureDetector(
      onTap: () => onTabSelected(tab),
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingSm),
        decoration: BoxDecoration(
          color: isActive
              ? DesignTokens.colorPrimary
              : DesignTokens.colorSurfaceElevated,
          borderRadius: BorderRadius.circular(DesignTokens.radiusMd),
          border: Border.all(color: DesignTokens.colorBorder),
        ),
        alignment: Alignment.center,
        child: Text(
          label,
          style: DesignTokens.textLabelMd.copyWith(
            color: isActive
                ? DesignTokens.colorOnPrimary
                : DesignTokens.colorTextPrimary,
          ),
        ),
      ),
    );
  }
}

